   print(seen,name,size,'comp_req',oldco,flush=True);seen+=1;state='skip';remain=size+((-size)%512)
  else:
   if not pending:break
   take=min(len(pending),remain);pending=pending[take:];remain-=take
   if remain==0:state='header'
 if ix%10==9:print('progress comp',co,'pending',len(pending),flush=True)
 if len(b)<chunk:print('short',len(b));break
print('done seen',seen,'comp',co,'pending',len(pending))
